import cats.effect.Sync
import cats.implicits._
import fs2.concurrent.SignallingRef
import grackle._
import grackle.syntax._

class ValueEffectMapping[F[_]: Sync](ref: SignallingRef[F, Int]) extends ValueMapping[F] {
  val schema =
    schema"""
      type Query { foo: Struct! }
      type Struct { n: Int!  s: String! }
    """

  val QueryType  = schema.ref("Query")
  val StructType = schema.ref("Struct")

  case class Struct(n: Int, s: String)

  val typeMappings = List(
    ObjectMapping(
      tpe = QueryType,
      fieldMappings = List(
        // runs once, before the rest of the query, and yields a root Cursor
        RootEffect.computeCursor("foo")((p, e) =>
          ref.update(_ + 1).as(Result(valueCursor(p, e, Struct(42, "hi")))))
      )
    ),
    ValueObjectMapping[Struct](
      tpe = StructType,
      fieldMappings = List(
        ValueField("n", _.n),
        ValueField("s", _.s)
      )
    )
  )
}

