import cats.effect.Sync
import cats.implicits._
import fs2.concurrent.SignallingRef
import io.circe.{Encoder, Json}
import grackle._
import grackle.circe.CirceMapping
import grackle.syntax._

class TestCirceEffectMapping[F[_]: Sync](ref: SignallingRef[F, Int]) extends CirceMapping[F] {
  val schema =
    schema"""
      type Query { foo: Struct!  bar: Struct!  baz: Struct!  qux: Struct! }
      type Struct { n: Int!  s: String! }
    """

  val QueryType  = schema.ref("Query")
  val StructType = schema.ref("Struct")

  case class Struct(n: Int, s: String)
  implicit val EncodeStruct: Encoder[Struct] = s =>
    Json.obj("n" -> Json.fromInt(s.n), "s" -> Json.fromString(s.s))

  val typeMappings = List(
    ObjectMapping(
      tpe = QueryType,
      fieldMappings = List(
        // build the cursor yourself
        RootEffect.computeCursor("foo")((p, e) =>
          ref.update(_ + 1).as(Result(circeCursor(p, e,
            Json.obj("n" -> Json.fromInt(42), "s" -> Json.fromString("hi")))))),
        // return raw Json, the mapping builds the cursor
        RootEffect.computeJson("bar")((_, _) =>
          ref.update(_ + 1).as(Result(
            Json.obj("n" -> Json.fromInt(42), "s" -> Json.fromString("ho"))))),
        // return an Encodable value, the mapping encodes + builds the cursor
        RootEffect.computeEncodable("baz")((_, _) =>
          ref.update(_ + 1).as(Result(Struct(44, "hee")))),
        // cursor focussed on the root rather than the field
        RootEffect.computeCursor("qux")((p, e) =>
          ref.update(_ + 1).as(Result(circeCursor(Path.from(p.rootTpe), e,
            Json.obj("qux" -> Json.obj("n" -> Json.fromInt(42), "s" -> Json.fromString("hi")))))))
      )
    )
  )
}

